{
  "correction_rules": [
    "Reduce forecast overshoots following sharp price spikes (e.g., >75% of 30d forecast exceeds true outcome by >5% in 3 consecutive days).",
    "Apply downward bias correction when sentiment history shows negative sentiment (e.g., -0.25 or below) for 2+ consecutive days, especially in 30d horizon.",
    "Adjust forecasts toward historical mean of last 18 days if model shows persistent overestimation (e.g., 3+ consecutive forecast > true outcome by >3% above 70.00).",
    "Apply lag correction: if true outcome is lower than forecast, reduce forecast by 0.5–1.0% per day for 2–3 days of lagged underperformance.",
    "Avoid overconfidence in short-term momentum: if 30d forecast shows >10% upward trend from prior 7d, reduce forecast by 10–15% to account for mean reversion."
  ]
}
